"use client";

import React, { useState, useMemo } from "react";
import { 
  Calendar, Info, AlertTriangle, FileText, 
  Users, TrendingDown, CheckCircle2, ShieldAlert,
  Clock, ArrowRight, DownloadCloud
} from "lucide-react";

export default function GlobalAbsencePortal() {
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    type: "annual",
    start: "",
    end: "",
    delegateId: "",
    reason: "",
  });

  // Business Logic: Real-time conflict & balance engine
  const insights = useMemo(() => {
    return {
      workingDays: 4, // Logic to exclude weekends/holidays
      teamConflict: true, // Mock logic: Sarah and Mike are also out
      payImpact: 0, // No deduction for annual leave
      newBalance: 14, // 18 - 4
    };
  }, [formData]);

  return (
    <div className="min-h-screen bg-[#F8FAFC] p-6 text-slate-900 dark:bg-[#020617] dark:text-slate-100">
      <div className="mx-auto max-w-7xl">
        
        {/* Header Area: High-End Context */}
        <header className="mb-10 flex flex-col justify-between gap-4 md:flex-row md:items-center">
          <div>
            <h1 className="text-3xl font-extrabold tracking-tight">Time Off Command</h1>
            <p className="text-slate-500 dark:text-slate-400">Manage your presence and team synchronization.</p>
          </div>
          <div className="flex items-center gap-3 rounded-2xl bg-white p-2 shadow-sm ring-1 ring-slate-200 dark:bg-slate-900 dark:ring-slate-800">
            <div className="flex -space-x-2 px-2">
              {[1, 2, 3].map(i => <div key={i} className="h-8 w-8 rounded-full border-2 border-white bg-slate-200 dark:border-slate-900" />)}
            </div>
            <div className="pr-3 text-xs font-medium border-l pl-3 border-slate-200 dark:border-slate-800">
              <span className="block text-emerald-500">Live Status</span>
              4 Peers Out Today
            </div>
          </div>
        </header>

        <div className="grid grid-cols-1 gap-8 lg:grid-cols-12">
          
          {/* LEFT: The Intelligent Form (6 Cols) */}
          <div className="lg:col-span-7 space-y-6">
            <div className="rounded-[2rem] border border-slate-200 bg-white p-8 shadow-xl shadow-slate-200/50 dark:border-slate-800 dark:bg-slate-900/50 dark:shadow-none">
              <h3 className="mb-6 text-lg font-bold flex items-center gap-2">
                <Calendar className="h-5 w-5 text-blue-500" /> 
                Request Configuration
              </h3>
              
              <div className="grid gap-6">
                {/* Leave Type Grid */}
                <div className="grid grid-cols-2 gap-3 sm:grid-cols-3">
                  {['Annual', 'Sick', 'Parental', 'Legal', 'Volunteer', 'L.O.P'].map((t) => (
                    <button 
                      key={t}
                      className={`group relative rounded-2xl border p-4 text-left transition-all ${
                        formData.type === t.toLowerCase() 
                        ? "border-blue-500 bg-blue-50/50 ring-1 ring-blue-500 dark:bg-blue-500/10" 
                        : "border-slate-100 hover:border-slate-300 dark:border-slate-800 dark:hover:border-slate-700"
                      }`}
                      onClick={() => setFormData({...formData, type: t.toLowerCase()})}
                    >
                      <span className="block text-sm font-bold">{t}</span>
                      <span className="text-[10px] text-slate-400">Policy #44-A</span>
                    </button>
                  ))}
                </div>

                <div className="grid grid-cols-2 gap-4 mt-2">
                  <InputBlock label="Start Date" type="date" />
                  <InputBlock label="End Date" type="date" />
                </div>

                <div>
                  <label className="text-xs font-bold uppercase tracking-widest text-slate-400">Coverage Delegate</label>
                  <select className="mt-2 w-full rounded-xl border-slate-200 bg-slate-50 p-3 text-sm focus:ring-2 focus:ring-blue-500 dark:border-slate-800 dark:bg-slate-900">
                    <option>Search for a colleague to handle approvals...</option>
                    <option>Sarah Jenkins (Senior Lead)</option>
                    <option>Marcus Aurelius (Project Manager)</option>
                  </select>
                </div>

                <textarea 
                  placeholder="Handoff details or reason for absence..."
                  className="w-full rounded-xl border-slate-200 bg-slate-50 p-4 text-sm dark:border-slate-800 dark:bg-slate-900"
                  rows={4}
                />
              </div>

              <div className="mt-8 flex items-center justify-between border-t border-slate-100 pt-6 dark:border-slate-800">
                <div className="flex gap-2">
                  <span className="h-3 w-3 rounded-full bg-emerald-500 animate-pulse" />
                  <span className="text-xs text-slate-500">Auto-saving as draft...</span>
                </div>
                <button className="flex items-center gap-2 rounded-xl bg-slate-900 px-8 py-3 font-bold text-white transition hover:bg-black dark:bg-blue-600 dark:hover:bg-blue-500">
                  Submit Request <ArrowRight className="h-4 w-4" />
                </button>
              </div>
            </div>
          </div>

          {/* RIGHT: Live Insights & Policy (5 Cols) */}
          <div className="lg:col-span-5 space-y-6">
            
            {/* Real-time Impact Assessment */}
            <div className="rounded-[2rem] bg-slate-900 p-8 text-white">
              <h4 className="text-xs font-bold uppercase tracking-[0.2em] text-slate-400">Impact Assessment</h4>
              
              <div className="mt-8 grid grid-cols-2 gap-8">
                <div>
                  <p className="text-3xl font-light">{insights.workingDays} <span className="text-sm opacity-50 uppercase">Days</span></p>
                  <p className="mt-1 text-xs text-slate-400 italic font-medium">Excl. weekends</p>
                </div>
                <div>
                  <p className="text-3xl font-light text-blue-400">{insights.newBalance} <span className="text-sm opacity-50 uppercase">Left</span></p>
                  <p className="mt-1 text-xs text-slate-400 font-medium italic">Projected Balance</p>
                </div>
              </div>

              {insights.teamConflict && (
                <div className="mt-8 flex gap-4 rounded-2xl bg-white/5 p-4 ring-1 ring-white/10">
                  <TrendingDown className="h-6 w-6 text-amber-400 shrink-0" />
                  <div>
                    <p className="text-sm font-bold">Team Availability Warning</p>
                    <p className="text-xs text-slate-400 mt-1 leading-relaxed">
                      Engineering capacity will drop below <span className="text-white">60%</span> during these dates. Your manager may require a coverage plan.
                    </p>
                  </div>
                </div>
              )}
            </div>

            {/* Smart Policy Checklist */}
            <div className="rounded-[2rem] border border-slate-200 bg-white p-8 dark:border-slate-800 dark:bg-slate-900/50">
              <h4 className="text-sm font-bold">Policy Compliance</h4>
              <ul className="mt-6 space-y-4">
                <PolicyItem checked text="Within annual carry-forward limit" />
                <PolicyItem checked text="No overlap with black-out period" />
                <PolicyItem checked={false} text="Medical cert required (>3 days sick)" warning />
                <PolicyItem checked text="Direct manager notified" />
              </ul>
            </div>

            {/* Financial Preview */}
            <div className="rounded-[2rem] bg-emerald-50 p-6 dark:bg-emerald-500/5">
              <div className="flex justify-between items-start">
                <div>
                  <p className="text-xs font-bold text-emerald-800 dark:text-emerald-400 uppercase tracking-widest">Financial Impact</p>
                  <p className="mt-2 text-2xl font-bold text-emerald-950 dark:text-emerald-100">$0.00 <span className="text-sm font-normal opacity-60">Deduction</span></p>
                </div>
                <div className="p-3 bg-white dark:bg-slate-900 rounded-xl shadow-sm">
                  <DownloadCloud className="h-5 w-5 text-emerald-600" />
                </div>
              </div>
            </div>

          </div>
        </div>
      </div>
    </div>
  );
}

// --- High-End UI Helpers ---

function InputBlock({ label, type }: { label: string; type: string }) {
  return (
    <div className="space-y-2">
      <label className="text-[10px] font-bold uppercase tracking-widest text-slate-400">{label}</label>
      <input 
        type={type} 
        className="w-full rounded-xl border-slate-200 bg-slate-50 p-3 text-sm focus:ring-2 focus:ring-blue-500 dark:border-slate-800 dark:bg-slate-900" 
      />
    </div>
  );
}

function PolicyItem({ checked, text, warning }: { checked: boolean; text: string; warning?: boolean }) {
  return (
    <li className="flex items-center gap-3 text-sm">
      {checked ? (
        <CheckCircle2 className="h-4 w-4 text-emerald-500" />
      ) : warning ? (
        <ShieldAlert className="h-4 w-4 text-amber-500" />
      ) : (
        <div className="h-4 w-4 rounded-full border border-slate-300" />
      )}
      <span className={checked ? "text-slate-600 dark:text-slate-400" : "font-semibold text-slate-900 dark:text-white"}>
        {text}
      </span>
    </li>
  );
}